    private ActivityController<LauncherinPlayerActivity> lifecycle;private LauncherinPlayerActivity activity;private LauncherinMusicLibrary library;private ServiceController<LauncherinPlayerService> audio;
    private List<LauncherinTrack> tracks=new ArrayList<>();
    @Before public void create()throws Exception{new android.app.Instrumentation().setInTouchMode(false);Context c=RuntimeEnvironment.getApplication();library=new LauncherinMusicLibrary(c);
        String[] titles={"Sutilmente","Midnight City","Bring Me to Life","Faixa de exemplo 4","Faixa de exemplo 5","Faixa de exemplo 6"},artists={"Skank","M83","Evanescence","Banda de exemplo","Artista de exemplo","Banda de exemplo"};
        for(int i=0;i<6;i++)tracks.add(new LauncherinTrack(LauncherinNativeMusicTest.track(i).url,titles[i],artists[i],"https://example.org/art"+i+".jpg",180000,"youtube","https://example.org/artist"+i+".jpg"));
        library.write("queue",tracks.subList(0,3));library.write("favorites",tracks.subList(0,3));library.progress(0,35000);library.saveArtist(new LauncherinMusicLibrary.Artist("Evanescence","youtube",tracks.get(2).artistArt,"band"));library.saveArtist(new LauncherinMusicLibrary.Artist("Legião Urbana","youtube",tracks.get(1).artistArt,"band"));library.saveArtist(new LauncherinMusicLibrary.Artist("Skank","youtube",tracks.get(0).artistArt));
        lifecycle=Robolectric.buildActivity(LauncherinPlayerActivity.class).create();activity=lifecycle.get();activity.searchSource=(q,sc)->new ArrayList<>(tracks);LauncherinMusicArtwork images=field("images");images.loader=(ctx,src,w,h)->art(Math.floorMod(src.hashCode(),6),Math.min(w,960),Math.min(h,540));android.util.LruCache<String,Bitmap> cache=ReflectionHelpers.getField(images,"cache");for(int i=0;i<6;i++){cache.put(tracks.get(i).art+"|320x240",art(i,320,240));if(i<3){cache.put(tracks.get(i).artistArt+"|160x160",art(i,160,160));cache.put(tracks.get(i).art+"|128x128",art(i,128,128));}}java.io.File lyricsDir=new java.io.File(c.getCacheDir(),"player-lyrics");lyricsDir.mkdirs();String key=LauncherinMusicLibrary.hash("Sutilmente\nSkank\n180000".getBytes(java.nio.charset.StandardCharsets.UTF_8));try(OutputStream out=new FileOutputStream(new File(lyricsDir,key+".json"))){out.write(new org.json.JSONObject().put("trackName","Sutilmente").put("artistName","Skank").put("duration",180).put("syncedLyrics","[00:00]Linha de exemplo para visualizar\n[00:20]A letra acompanha a reprodução\n[00:40]Conteúdo ilustrativo desta captura").toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}lifecycle.start().resume().visible().windowFocusChanged(true);measure();Shadows.shadowOf(Looper.getMainLooper()).idle();
    }
    @After public void close(){lifecycle.pause().stop().destroy();if(audio!=null)audio.destroy();LauncherinIdle.stopListening();}
    private <T>T field(String name){return ReflectionHelpers.getField(activity,name);}
    private void call(String name){ReflectionHelpers.callInstanceMethod(activity,name);}
    private void select(String page){ReflectionHelpers.callInstanceMethod(activity,"select",ReflectionHelpers.ClassParameter.from(String.class,page));measure();Shadows.shadowOf(Looper.getMainLooper()).idle();}
    private void measure(){View v=activity.findViewById(android.R.id.content);v.measure(View.MeasureSpec.makeMeasureSpec(960,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(540,View.MeasureSpec.EXACTLY));v.layout(0,0,960,540);}
    private TextView button(String text){return find(activity.findViewById(android.R.id.content),text);}
    private static TextView find(View v,String s){if(v instanceof TextView&&(((TextView)v).getText().toString().equals(s)||s.equals(v.getContentDescription())||"Protetor".equals(s)&&"Protetor de áudio".contentEquals(v.getContentDescription()==null?"":v.getContentDescription())))return (TextView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){TextView t=find(((ViewGroup)v).getChildAt(i),s);if(t!=null)return t;}return null;}
    private Map<String,View> focuses(){return field("focusViews");}
    private void simulatedAudio(){audio=Robolectric.buildService(LauncherinPlayerService.class).create();ReflectionHelpers.setField(audio.get(),"state",PlaybackState.STATE_PLAYING);call("refresh");}
    @Test public void sidebarContentAndTransportHaveRemoteFocusRoutes(){assertNotNull(button("Início"));assertNotNull(button("Buscar"));assertNotNull(button("Favoritos"));assertNotNull(button("Fila"));call("focusContent");View play=field("heroPlay");assertTrue(play.hasFocus());assertEquals(((SeekBar)field("heroSeek")).getId(),play.getNextFocusUpId());assertEquals(focuses().get("quick:artists").getId(),play.getNextFocusDownId());assertEquals(button("Início").getId(),focuses().get("hero-queue").getNextFocusLeftId());}
    @Test public void searchFieldAndSubmitAreConnectedWithoutTouch(){select("search");EditText input=field("query");input.requestFocus();View submit=focuses().get("search-submit");assertEquals(submit.getId(),input.getNextFocusRightId());submit.requestFocus();assertTrue(submit.hasFocus());assertEquals(input.getId(),submit.getNextFocusLeftId());}
    @Test public void searchGridCanMoveDownThroughResultsBeforeReachingTransport(){ReflectionHelpers.setField(activity,"results",tracks);select("search");View first=focuses().get("track:"+tracks.get(0).url),last=focuses().get("track:"+tracks.get(3).url);TextView play=field("play");assertNotEquals(play.getId(),first.getNextFocusDownId());assertEquals(play.getId(),last.getNextFocusDownId());}
    @Test public void songsHaveVisibleActionsForPlayQueueSongAndArtistFavorites(){select("favorites");focuses().get("track:"+tracks.get(0).url).performClick();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();assertNotNull(d);CharSequence[] options=Shadows.shadowOf(d).getItems();assertEquals("Tocar agora",options[0]);assertEquals("Adicionar à fila",options[1]);assertEquals("Favoritar artista ou banda",options[3]);assertEquals(4,options.length);d.dismiss();}
    @Test public void favoriteArtistHasNamedBrowseEditAndRemoveActions(){focuses().get("quick:artists").performClick();focuses().get("artist:skank").performClick();assertEquals("search",field("tab"));assertEquals("Skank",((EditText)field("query")).getText().toString());focuses().get("artist-options").performClick();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();assertEquals("Ouvir músicas deste artista",Shadows.shadowOf(d).getItems()[0]);d.getListView().performItemClick(null,2,2);assertEquals(2,library.artists().size());assertFalse(library.artists().stream().anyMatch(a->a.name.equals("Skank")));}
    @Test public void manualArtistAddIsSavedWithoutResettingQueue(){focuses().get("quick:artists").performClick();focuses().get("add-artist").performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();EditText input=findInput(d.getWindow().getDecorView());assertNotNull(input);input.setText("Banda Nova");d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertTrue(library.artists().stream().anyMatch(a->a.name.equals("Banda Nova")));assertEquals(3,library.read("queue").size());assertEquals(35000,library.position());}
    private static EditText findInput(View v){if(v instanceof EditText)return (EditText)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){EditText input=findInput(((ViewGroup)v).getChildAt(i));if(input!=null)return input;}return null;}
    @Test public void saverMovesAndFirstOkOnlyReturnsToLibrary(){button("Protetor").performClick();measure();LauncherinAudioSaverView saver=field("saver");assertNotNull(saver);LinearLayout floating=ReflectionHelpers.getField(saver,"floating");FrameLayout.LayoutParams before=(FrameLayout.LayoutParams)floating.getLayoutParams();int x=before.leftMargin,y=before.topMargin;ShadowSystemClock.advanceBy(Duration.ofSeconds(21));saver.update(tracks.get(0),SystemClock.elapsedRealtime());FrameLayout.LayoutParams after=(FrameLayout.LayoutParams)floating.getLayoutParams();assertTrue(x!=after.leftMargin||y!=after.topMargin);activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_CENTER));activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_CENTER));assertNull(field("saver"));assertNull(Shadows.shadowOf((Application)RuntimeEnvironment.getApplication()).getNextStartedService());}
