    @Test public void allFourSaverChoicesStayInsideTheVisibleColumns(){select("settings");View container=field("content");Rect area=new Rect();assertTrue(container.getGlobalVisibleRect(area));for(String mode:new String[]{"cover","photos","dark","google"}){View choice=focuses().get("saver-mode:"+mode);int[] position=new int[2];choice.getLocationOnScreen(position);assertTrue(mode,position[0]>=area.left);assertTrue(mode,position[0]+choice.getWidth()<=area.right);}assertTrue(focuses().get("saver-mode:photos").getLeft()>focuses().get("saver-mode:cover").getLeft());}
    @Test public void photoSaverActuallyReceivesItsBackgroundBitmap()throws Exception{photoFixture();library.saverMode("photos");button("Protetor").performClick();measure();LauncherinAudioSaverView saver=field("saver");saver.update(tracks.get(0),SystemClock.elapsedRealtime());measure();drainImages();ImageView image=ReflectionHelpers.getField(saver,"background");assertEquals("photos",saver.actualMode());assertNotNull("Photo must be loaded instead of a black background",image.getDrawable());}
    @Test public void artworkOutsideTheViewportDropsItsBitmapReference(){ImageView image=field("heroArt");LauncherinMusicArtwork art=field("images");try{drainImages();}catch(Exception e){throw new AssertionError(e);}art.visible();assertNotNull(image.getTag());image.setVisibility(View.GONE);art.visible();assertNull("Hidden pictures must not retain decoded bitmaps outside the bounded cache",image.getTag());}
