    @Test public void foregroundTvIconStillHasVisiblePixels(){TextView tv=new TextView(activity);tv.setForeground(activity.getDrawable(R.drawable.ic_live_tv));tv.setForegroundGravity(Gravity.CENTER);tv.measure(View.MeasureSpec.makeMeasureSpec(48,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(48,View.MeasureSpec.EXACTLY));tv.layout(0,0,48,48);Bitmap b=Bitmap.createBitmap(48,48,Bitmap.Config.ARGB_8888);tv.draw(new Canvas(b));int pixels=0;for(int y=0;y<48;y++)for(int x=0;x<48;x++)if(Color.alpha(b.getPixel(x,y))>100)pixels++;assertTrue(pixels>40);}
    @Test public void widgetLongOkStillOpensOwnPlayerWithoutMediaAccess(){ActivityController<LauncherinVisualPreviewTest.PreviewHost> host=Robolectric.buildActivity(LauncherinVisualPreviewTest.PreviewHost.class).setup();LauncherinAudioWidget widget=new LauncherinAudioWidget(host.get(),false);Button b=ReflectionHelpers.getField(widget,"play");assertTrue(b.performLongClick());Intent launch=Shadows.shadowOf(host.get()).getNextStartedActivity();assertEquals(LauncherinPlayerActivity.class.getName(),launch.getComponent().getClassName());widget.close();host.pause().stop().destroy();}
