    @Test public void captureNativeApprovedLayoutAndAllLocalSaverModes()throws Exception{simulatedAudio();call("focusContent");drainLyrics();save("music-now-playing");button("Letra").performClick();measure();save("music-lyrics");activity.onBackPressed();button("Artistas").performClick();measure();save("music-artists");button("Bandas").performClick();measure();save("music-bands");ReflectionHelpers.setField(activity,"results",tracks);select("search");save("music-search");select("queue");save("music-queue");select("settings");save("music-protection-settings");select("home");for(String mode:new String[]{"cover","dark","photos"}){library.saverMode(mode);if(mode.equals("photos"))photoFixture();button("Protetor").performClick();measure();LauncherinAudioSaverView saver=field("saver");saver.update(tracks.get(0),SystemClock.elapsedRealtime());measure();drainImages();save("music-saver-"+mode);activity.onBackPressed();} }
    private void drainLyrics()throws Exception{java.util.concurrent.ExecutorService worker=field("lyricWorker");worker.submit(()->{}).get(3,java.util.concurrent.TimeUnit.SECONDS);Shadows.shadowOf(Looper.getMainLooper()).idle();}
    @Test public void heroAndLyricsAndQuickCardsFitWithoutOverlap(){View content=field("content");Rect area=new Rect();content.getGlobalVisibleRect(area);for(String key:new String[]{"hero-play","hero-lyrics","quick:artists","quick:bands","quick:songs"}){View v=focuses().get(key);int[] pos=new int[2];v.getLocationOnScreen(pos);assertTrue(key,pos[0]>=area.left&&pos[1]>=area.top);assertTrue(key,pos[0]+v.getWidth()<=area.right&&pos[1]+v.getHeight()<=area.bottom);}assertEquals(View.GONE,((View)field("bar")).getVisibility());assertTrue(((View)field("heroArt")).getWidth()>150);}
    @Test public void nowPlayingMetadataAndLyricsUpdateWithoutRebuildingTheCard()throws Exception{View hero=field("heroPlay");assertEquals("Sutilmente",((TextView)field("heroTitle")).getText().toString());drainLyrics();assertTrue(((TextView)field("lyricPreview")).getText().toString().contains("A letra acompanha"));call("refresh");assertSame(hero,field("heroPlay"));assertNull(button("FLAC"));assertNull(button("Dolby Audio"));assertNull(button("Lossless"));}
    @Test public void topTabsSeparateBandsAndArtistsWithoutLosingFavorites(){button("Bandas").performClick();measure();assertNotNull(focuses().get("artist:evanescence"));assertNull(focuses().get("artist:skank"));button("Artistas").performClick();measure();assertNotNull(focuses().get("artist:skank"));assertNull(focuses().get("artist:evanescence"));assertEquals(3,library.artists().size());assertEquals(35000,library.position());}
    @Test public void heroFavoriteAndQueueActionsAreReal(){int initial=library.read("favorites").size();focuses().get("favorite-current").performClick();assertEquals(initial-1,library.read("favorites").size());assertEquals("Favoritar",((TextView)field("heroFavorite")).getText().toString());focuses().get("hero-queue").performClick();assertEquals("queue",field("tab"));assertEquals(View.VISIBLE,((View)field("bar")).getVisibility());}
    @Test public void movingArtistToBandPersistsWithoutDuplicatingOrResettingPlayback(){focuses().get("quick:artists").performClick();View artist=focuses().get("artist:skank");artist.performLongClick();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();d.getListView().performItemClick(null,1,1);Shadows.shadowOf(Looper.getMainLooper()).idle();d=ShadowAlertDialog.getLatestAlertDialog();TextView category=find(d.getWindow().getDecorView(),"Categoria: Artista");assertNotNull(category);category.performClick();d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(3,library.artists().size());assertEquals("band",library.artists().stream().filter(a->a.name.equals("Skank")).findFirst().get().kind);assertEquals(35000,library.position());button("Bandas").performClick();assertNotNull(focuses().get("artist:skank"));}
    @Test public void currentTrackOptionsKeepTheExistingQueueContext(){focuses().get("hero-options").performClick();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();assertEquals("Tocar a partir desta música",Shadows.shadowOf(d).getItems()[0]);assertEquals(3,library.read("queue").size());d.dismiss();}
    private void drainImages()throws Exception{LauncherinMusicArtwork image=field("images");java.util.concurrent.ExecutorService worker=ReflectionHelpers.getField(image,"worker");for(int i=0;i<4;i++){worker.submit(()->{}).get(2,java.util.concurrent.TimeUnit.SECONDS);Shadows.shadowOf(Looper.getMainLooper()).idle();}}
    private void photoFixture()throws Exception{File dir=Config.dir(activity);if(dir==null)dir=activity.getFilesDir();dir.mkdirs();String id="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";File image=new File(dir,"frame-"+id.substring(0,40)+".jpg");try(OutputStream out=new FileOutputStream(image)){art(3,960,540).compress(Bitmap.CompressFormat.JPEG,85,out);}org.json.JSONObject data=LauncherinExtras.read(activity);data.put("frame_photos",new org.json.JSONArray().put(id));try(OutputStream out=new FileOutputStream(new File(dir,"config.json"))){out.write(data.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
    private Bitmap art(int n,int width,int height){Bitmap b=Bitmap.createBitmap(width,height,Bitmap.Config.RGB_565);Canvas c=new Canvas(b);Paint p=new Paint(3);int[] top={0xff865d36,0xff223552,0xff163c46,0xff355c4c,0xff674855,0xff39324f};p.setShader(new LinearGradient(0,0,width,height,new int[]{top[n%6],0xff07161c},null,Shader.TileMode.CLAMP));c.drawRect(0,0,width,height,p);p.setShader(null);p.setColor(n%2==0?0xffd4ac75:0xff9bafbb);c.drawCircle(width*.65f,height*.32f,width*.17f,p);p.setColor(0xff17363c);Path hill=new Path();hill.moveTo(0,height*.8f);hill.cubicTo(width*.3f,height*.25f,width*.55f,height,width,height*.45f);hill.lineTo(width,height);hill.lineTo(0,height);c.drawPath(hill,p);p.setColor(0xff0b252b);hill.reset();hill.moveTo(0,height*.85f);hill.cubicTo(width*.4f,height,width*.65f,height*.4f,width,height*.76f);hill.lineTo(width,height);hill.lineTo(0,height);c.drawPath(hill,p);return b;}
    private void save(String name)throws Exception{measure();drainImages();View view=activity.findViewById(android.R.id.content);Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);view.draw(c);Paint p=new Paint(3);p.setColor(0xffa6b7c8);p.setTextSize(8);c.drawText("PRÉVIA LOCAL · COMPONENTES ANDROID · MÚSICAS E ARTES DE EXEMPLO",24,534,p);File dir=new File("/tmp/launcherin21/captures");dir.mkdirs();try(OutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}}
